import{_ as a,o as i,c as n,a5 as t}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"Identification Workflow & Documentation","description":"","frontmatter":{"title":"Identification Workflow & Documentation","identification":"identification-workflow"},"headers":[],"relativePath":"identification/identification-workflow.md","filePath":"identification/identification-workflow.md","lastUpdated":1790876393000}'),r={name:"identification/identification-workflow.md"};function o(s,e,l,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="identification-workflow-documentation" tabindex="-1">Identification Workflow &amp; Documentation <a class="header-anchor" href="#identification-workflow-documentation" aria-label="Permalink to &quot;Identification Workflow &amp; Documentation&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Professional identification is not a search for one “magic reading”; it is a reproducible chain of evidence. Record the sample first, begin with low-risk observations, combine physical, optical, and inclusion clues, then state the confidence limits, treatment disclosure, and whether a laboratory report is needed.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-identification-workflow-en"><p class="gem-identification-boundary__eyebrow">IDENTIFICATION BOUNDARY</p><h2 id="identification-boundary-identification-workflow-en">Boundary &amp; Safety</h2><p>This page teaches evidence organization, not specimen certification. State observation conditions, incomplete tests, and sample limits; do not establish natural, synthetic, treatment, origin, or value from a photo or single reading. Refer high-value or formal disclosure decisions to a qualified lab. </p></aside><h2 id="identification-steps" tabindex="-1">Identification Steps <a class="header-anchor" href="#identification-steps" aria-label="Permalink to &quot;Identification Steps&quot;">​</a></h2><p><strong>1. Record the sample and scope</strong></p><p>Note dimensions, weight, mounting, known provenance, visible damage, and the purpose of the examination. Record which tests are unreliable or unavailable for mounted, oiled, or inaccessible samples.</p><p><strong>2. Start with non-destructive observation</strong></p><p>Under white light, a point source, and suitable magnification, record body color, transparency, luster, cut, inclusions, and phenomena. Write observations before candidate names.</p><p><strong>3. Escalate tests by risk</strong></p><p>Prefer refractive index, polariscope, dichroscope, UV fluorescence, and spectroscopy as non-destructive clues. Assess whether a specific-gravity liquid test is suitable; scratch testing requires a clear need and permission.</p><p><strong>4. Cross-check and grade the conclusion</strong></p><p>Compare readings with candidate ranges, treatment possibilities, and sample limitations. Distinguish “supports a candidate”, “consistent with a candidate”, and “cannot exclude”; a single test is not a final ID.</p><p><strong>5. Refer to a laboratory when needed</strong></p><p>For natural-versus-synthetic decisions, origin opinions, major transactions, or insurance, preserve raw observations and refer the sample to a qualified laboratory for advanced testing.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Keep separate fields for “what was observed” and “what it suggests” so observation and conclusion do not contaminate each other.</li><li>Record test conditions, orientation, contact state, and repeated readings; values cannot be compared without context.</li><li>Keep the conclusion weaker than the evidence: a screen is not a certificate, and an origin opinion is not a grade.</li><li>Confirm permission, sample value, and safety conditions before any destructive test.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Value</th><th>Note</th></tr></thead><tbody><tr><td>mounted ruby</td><td>screen first; report inaccessible tests</td><td>mounting limits access</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gems-gemology/winter-2024-gemstone-analysis" target="_blank" rel="noreferrer">GIA: Analysis of Gemstones at GIA Laboratories</a><span>Standard gemological testing, laboratory workflow, and laboratory-grown diamond analysis examples</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA: Analytical Methods Used in Geographic Origin Determination</a><span>RI/SG as an identification starting point and further analysis for origin opinions</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2024-infrared-spectroscopy" target="_blank" rel="noreferrer">GIA: Infrared Spectroscopy and Its Use in Gemology</a><span>Spectroscopy and its relationship to atomic structure and natural/synthetic/treatment clues</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/ruby" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Ruby</a><span>Typical ruby RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/sapphire" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Sapphire</a><span>Typical sapphire RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/emerald" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Emerald</a><span>Typical emerald RI, birefringence, specific gravity, hardness, and treatment/synthetic/imitation context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/spinel" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Spinel</a><span>Typical spinel RI, isotropy, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/diamond" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Diamond</a><span>Typical diamond RI, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/zircon" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Zircon</a><span>Typical zircon RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/articles/iolite-description" target="_blank" rel="noreferrer">GIA: Iolite Description</a><span>Iolite pleochroism and viewing-direction context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/tanzanite-description" target="_blank" rel="noreferrer">GIA: Tanzanite Description</a><span>Tanzanite pleochroism, orientation, lighting, and heat-treatment context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/peridot" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Peridot</a><span>Typical peridot RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://my.gia.edu/FAQ/gia-faq-two-green-garnet" target="_blank" rel="noreferrer">GIA FAQ: Tsavorite and Demantoid</a><span>Green garnet colour overlap and mineral distinction context</span><small>Open source ↗</small></li></ul></aside><p><em>See the <a href="./intro.html">identification overview</a>.</em></p>',21)])])}const h=a(r,[["render",o]]);export{m as __pageData,h as default};
